<?php
declare(strict_types=1);

require __DIR__.'/bootstrap.php';
require tamiran_private_root().'/sms-service.php';

tamiran_api(static function():array{
    $config=tamiran_config();$isCli=PHP_SAPI==='cli';$expected=(string)($config['sms']['cron_token']??'');$provided=(string)($_SERVER['HTTP_X_TAMIRAN_SMS_TOKEN']??$_GET['token']??'');if(!$isCli&&(!tamiran_secret_is_configured($expected)||!hash_equals($expected,$provided)))throw new TamiranApiException('دسترسی worker پیامک مجاز نیست.',403);$pdo=tamiran_db();$pdo->beginTransaction();try{$rows=$pdo->query("SELECT m.*,p.provider_code,p.credentials_ciphertext,p.settings_json FROM tamiran_sms_messages m INNER JOIN tamiran_sms_providers p ON p.id=m.provider_id WHERE m.status IN ('queued','failed') AND m.next_attempt_at<=NOW() AND m.attempts<m.max_attempts AND p.is_active=1 ORDER BY m.next_attempt_at,m.id LIMIT 20 FOR UPDATE")->fetchAll();if($rows!==[]){$ids=array_map('intval',array_column($rows,'id'));$pdo->exec("UPDATE tamiran_sms_messages SET status='processing' WHERE id IN (".implode(',',$ids).')');}$pdo->commit();}catch(Throwable$error){if($pdo->inTransaction())$pdo->rollBack();throw$error;}$sent=0;$failed=0;foreach($rows as$row){try{$provider=tamiran_sms_provider_from_row($row);$result=$provider->send((string)$row['recipient_mobile'],(string)$row['body']);$pdo->prepare("UPDATE tamiran_sms_messages SET status='sent',provider_message_id=:provider_message,attempts=attempts+1,last_error=NULL,sent_at=NOW() WHERE id=:id AND status='processing'")->execute(['provider_message'=>$result['messageId'],'id'=>$row['id']]);$sent++;}catch(Throwable$error){$attempt=(int)$row['attempts']+1;$delay=min(3600,30*(2**min(7,$attempt)));$pdo->prepare("UPDATE tamiran_sms_messages SET status='failed',attempts=:attempts,next_attempt_at=DATE_ADD(NOW(),INTERVAL :delay SECOND),last_error=:error WHERE id=:id AND status='processing'")->execute(['attempts'=>$attempt,'delay'=>$delay,'error'=>substr($error->getMessage(),0,1000),'id'=>$row['id']]);$failed++;tamiran_log('warning','sms_delivery_failed',['message_public_id'=>$row['public_id'],'attempt'=>$attempt,'message'=>$error->getMessage()]);}}return['processed'=>count($rows),'sent'=>$sent,'failed'=>$failed];
});
